diff --git a/libavcodec/shorten.c b/libavcodec/shorten.c
index 12a179156a..b846aa2486 100644
--- a/libavcodec/shorten.c
+++ b/libavcodec/shorten.c
@@ -556,52 +556,52 @@ static int shorten_decode_frame(AVCodecContext *avctx, AVFrame *frame,
         memmove(s->bitstream, &s->bitstream[s->bitstream_index],
                 s->bitstream_size);
         s->bitstream_index = 0;
     }
     if (buf)
         memcpy(&s->bitstream[s->bitstream_index + s->bitstream_size], buf,
                buf_size);
     buf               = &s->bitstream[s->bitstream_index];
     buf_size         += s->bitstream_size;
     s->bitstream_size = buf_size;
-    memset(buf + buf_size, 0, AV_INPUT_BUFFER_PADDING_SIZE);

     /* do not decode until buffer has at least max_framesize bytes or
      * the end of the file has been reached */
     if (buf_size < s->max_framesize && avpkt->data) {
         *got_frame_ptr = 0;
         return input_buf_size;
     }
     /* init and position bitstream reader */
     if ((ret = init_get_bits8(&s->gb, buf, buf_size)) < 0)
         return ret;
     skip_bits(&s->gb, s->bitindex);

     /* process header or next subblock */
     if (!s->got_header) {

         if ((ret = read_header(s)) < 0)
             return ret;

         if (avpkt->size) {
-            int max_framesize;
+            int max_framesize = s->blocksize * s->channels * 8;
             void *tmp_ptr;
-
-            max_framesize = FFMAX(s->max_framesize, s->blocksize * s->channels * 8);
+            unsigned old_allocated_bitstream_size = s->allocated_bitstream_size;
             tmp_ptr = av_fast_realloc(s->bitstream, &s->allocated_bitstream_size,
                                       max_framesize + AV_INPUT_BUFFER_PADDING_SIZE);
             if (!tmp_ptr) {
                 av_log(avctx, AV_LOG_ERROR, "error allocating bitstream buffer\n");
                 return AVERROR(ENOMEM);
             }
             s->bitstream = tmp_ptr;
-            s->max_framesize = max_framesize;
+            if (s->allocated_bitstream_size > old_allocated_bitstream_size)
+                memset(s->bitstream + old_allocated_bitstream_size, 0, s->allocated_bitstream_size - old_allocated_bitstream_size);
+            s->max_framesize = FFMAX(s->max_framesize, max_framesize);
             *got_frame_ptr = 0;
             goto finish_frame;
         }
     }

     /* if quit command was read previously, don't decode anything */
     if (s->got_quit_command) {
         *got_frame_ptr = 0;
         return avpkt->size;
     }

